/** This project's own handlers (E11's universe), not Bohemia's. */
const OWN_PREFIX = "EMCP_WB_";
/**
 * Functions that take the APIFunc and the request: the client's `call` and
 * `rawCall` (name, request) and the protocol's `encodeRequest` (clientId,
 * name, request). Matched as `x.call(...)`, `x["call"](...)` and a bare
 * `call(...)` (a destructured or bound method).
 */
const CALL_METHODS = new Map<string, { nameArg: number; reqArg: number }>([
  ["call", { nameArg: 0, reqArg: 1 }],
  ["rawCall", { nameArg: 0, reqArg: 1 }],
  // The client's lease-free read path, its queued retry job and its per-socket exchange (DEC-048 package A):
  // both forward their own parameter, so they are API, not call sites.
  ["probe", { nameArg: 0, reqArg: 1 }],
  ["exchange", { nameArg: 0, reqArg: 1 }],
  ["sendWithRetry", { nameArg: 0, reqArg: 1 }],
  ["encodeRequest", { nameArg: 1, reqArg: 2 }],
]);

export interface CallFinding {
  file: string;
  line: number;
  /** The APIFunc, or null when the source computes it and it could not be resolved. */
  name: string | null;
  /** Request keys, or null when the request is not an object literal this scan can read. */
  keys: string[] | null;
  why?: string;
}

function unwrap(e: ts.Expression): ts.Expression {
  let x = e;
  while (
    ts.isParenthesizedExpression(x) ||
    ts.isAsExpression(x) ||
    ts.isTypeAssertionExpression(x) ||
    ts.isNonNullExpression(x) ||
    ts.isSatisfiesExpression(x)
  )
    x = x.expression;
  return x;
}

function literalText(e: ts.Expression | undefined): string | undefined {
  if (!e) return undefined;
  const x = unwrap(e);
  return ts.isStringLiteral(x) || ts.isNoSubstitutionTemplateLiteral(x) ? x.text : undefined;
}

/** The string a module-level `const NAME = "..."` of `source` binds, when `e` is that identifier. */
function moduleConstText(source: ts.SourceFile, e: ts.Expression): string | undefined {
  const id = unwrap(e);
  if (!ts.isIdentifier(id)) return undefined;
  for (const st of source.statements) {
    if (!ts.isVariableStatement(st)) continue;
    if (!(st.declarationList.flags & ts.NodeFlags.Const)) continue;
    for (const d of st.declarationList.declarations) {
      if (ts.isIdentifier(d.name) && d.name.text === id.text && d.initializer) {
        return literalText(d.initializer);
      }
    }
  }
  return undefined;
}

/** The client method a call goes through: `x.call`, `x["call"]` or a bare `call`. */
function calleeMethod(call: ts.CallExpression): string | undefined {
  const c = unwrap(call.expression);
  const name = ts.isPropertyAccessExpression(c)
    ? c.name.text
    : ts.isElementAccessExpression(c)
      ? literalText(c.argumentExpression)
      : ts.isIdentifier(c)
        ? c.text
        : undefined;
  return name !== undefined && CALL_METHODS.has(name) ? name : undefined;
}

function objectKeys(e: ts.Expression | undefined): { keys: string[] | null; why?: string } {
  if (e === undefined) return { keys: [] };
  const x = unwrap(e);
  if (!ts.isObjectLiteralExpression(x))
    return { keys: null, why: "request is not an object literal" };
  const keys: string[] = [];
  for (const p of x.properties) {
    if (ts.isSpreadAssignment(p))
      return { keys: null, why: "request object spreads another object" };
    const n = p.name;
    if (n && (ts.isIdentifier(n) || ts.isStringLiteral(n) || ts.isNumericLiteral(n)))
      keys.push(n.text);
    else return { keys: null, why: "request object has a computed key" };
  }
  return { keys };
}

type Fn = ts.FunctionDeclaration | ts.ArrowFunction | ts.FunctionExpression | ts.MethodDeclaration;

function enclosingFunction(n: ts.Node): Fn | undefined {
  for (let p = n.parent; p; p = p.parent)
    if (
      ts.isFunctionDeclaration(p) ||
      ts.isArrowFunction(p) ||
      ts.isFunctionExpression(p) ||
      ts.isMethodDeclaration(p)
    )
      return p;
  return undefined;
}

function functionName(f: Fn): string | undefined {
  if (
    (ts.isFunctionDeclaration(f) || ts.isMethodDeclaration(f)) &&
    f.name &&
    ts.isIdentifier(f.name)
  )
    return f.name.text;
  if (f.parent && ts.isVariableDeclaration(f.parent) && ts.isIdentifier(f.parent.name))
    return f.parent.name.text;
  return undefined;
}

function paramIndex(f: Fn, name: string): number {
  return f.parameters.findIndex((p) => ts.isIdentifier(p.name) && p.name.text === name);
}

/** A function that forwards its parameter as the APIFunc: its callers are the call sites. */
interface Wrapper {
  file: string;
  fname: string;
  /** Parameter index of the APIFunc. */
  pi: number;
  /** Parameter index of the request, or -1 when the wrapper builds it itself. */
  pj: number;
  /** The request expression inside the wrapper (undefined: none sent). */
  req: ts.Expression | undefined;
  /** The "no caller" finding, dropped when another file calls the wrapper. */
  orphan?: CallFinding;
}

interface Parsed {
  file: string;
  sf: ts.SourceFile;
  calls: ts.CallExpression[];
}

function parse(file: string, text: string): Parsed {
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  const calls: ts.CallExpression[] = [];
  const collect = (n: ts.Node): void => {
    if (ts.isCallExpression(n)) calls.push(n);
    ts.forEachChild(n, collect);
  };
  collect(sf);
  return { file, sf, calls };
}

function lineOf(p: Parsed, n: ts.Node): number {
  return p.sf.getLineAndCharacterOfPosition(n.getStart(p.sf)).line + 1;
}

/** Findings at the callers `callers` (in file `p`) of wrapper `w`. */
function wrapperCallers(p: Parsed, w: Wrapper, callers: ts.CallExpression[]): CallFinding[] {
  return callers.map((c) => {
    // A literal, or a module-level const of the same file, as for a direct call (wb_shape names
    // its three handlers as consts and passes them to its callHandler wrapper).
    const arg = c.arguments[w.pi];
    const n2 = literalText(arg) ?? (arg === undefined ? undefined : moduleConstText(p.sf, arg));
    const k =
      w.req === undefined
        ? { keys: [] as string[] }
        : w.pj !== -1
          ? objectKeys(c.arguments[w.pj])
          : objectKeys(w.req);
    return {
      file: p.file,
      line: lineOf(p, c),
      name: n2 ?? null,
      ...k,
      ...(n2 === undefined ? { why: `computed APIFunc passed to ${w.fname}` } : {}),
    };
  });
}

function scanParsed(p: Parsed): { findings: CallFinding[]; wrappers: Wrapper[] } {
  const out: CallFinding[] = [];
  const wrappers: Wrapper[] = [];
  for (const call of p.calls) {
    const method = calleeMethod(call);
    if (method === undefined) continue;
    const { nameArg, reqArg } = CALL_METHODS.get(method)!;
    const a0 = call.arguments[nameArg];
    const a1 = call.arguments[reqArg];
    if (a0 === undefined) continue;
    // A literal, or a module-level `const HANDLER = "EMCP_WB_X"` of the same file (the Phase 3
    // tools name their handler once, DEC-048).
    const name = literalText(a0) ?? moduleConstText(p.sf, a0);
    if (name !== undefined) {
      out.push({ file: p.file, line: lineOf(p, call), name, ...objectKeys(a1) });
      continue;
    }
    // A name handed in through the enclosing function's parameter: resolve at its callers.
    const id = unwrap(a0);
    const fn = enclosingFunction(call);
    const fname = fn ? functionName(fn) : undefined;
    const pi = fn && ts.isIdentifier(id) ? paramIndex(fn, id.text) : -1;
    // The client's own call() / rawCall() forwarding its parameter is the API, not a call site.
    if (fn && fname && CALL_METHODS.has(fname) && pi !== -1) continue;
    if (!fn || !fname || pi === -1) {
      out.push({
        file: p.file,
        line: lineOf(p, call),
        name: null,
        keys: null,
        why: "computed APIFunc",
      });
      continue;
    }
    const bodyId = a1 !== undefined ? unwrap(a1) : undefined;
    const pj = bodyId && ts.isIdentifier(bodyId) ? paramIndex(fn, bodyId.text) : -1;
    const w: Wrapper = { file: p.file, fname, pi, pj, req: a1 };
    const callers = p.calls.filter((c) => {
      const e = unwrap(c.expression);
      return ts.isIdentifier(e) && e.text === fname;
    });
    if (callers.length === 0) {
      w.orphan = {
        file: p.file,
        line: lineOf(p, call),
        name: null,
        keys: null,
        why: `no caller of ${fname} in the scanned files`,
      };
      out.push(w.orphan);
    }
    out.push(...wrapperCallers(p, w, callers));
    wrappers.push(w);
  }
  return { findings: out, wrappers };
}

/** Every NET call in one TypeScript source (wrappers resolved within the file). */
export function scanSource(file: string, text: string): CallFinding[] {
  return scanParsed(parse(file, text)).findings;
}

/** `src/a/b.ts` importing `./c.js` gives `src/a/c` (no extension); undefined for a package. */
function importTarget(fromFile: string, spec: string): string | undefined {
  if (!spec.startsWith(".")) return undefined;
  return posix
    .normalize(posix.join(posix.dirname(fromFile), spec))
    .replace(/\.(js|ts|mjs|mts)$/, "");
}

/**
 * Every NET call in a set of sources (repository-relative paths). A wrapper
 * exported from one file is also resolved at its callers in every file that
 * imports it (named, renamed or namespace import).
 */
export function scanFiles(files: { file: string; text: string }[]): CallFinding[] {
  const parsed = files.map((f) => parse(f.file, f.text));
  const results = parsed.map(scanParsed);
  const out = results.flatMap((r) => r.findings);
  for (const w of results.flatMap((r) => r.wrappers)) {
    const target = w.file.replace(/\.ts$/, "");
    let external = 0;
    for (const p of parsed) {
      if (p.file === w.file) continue;
      const locals = new Set<string>();
      const namespaces = new Set<string>();
      for (const st of p.sf.statements) {
        if (!ts.isImportDeclaration(st) || !ts.isStringLiteral(st.moduleSpecifier)) continue;
        if (importTarget(p.file, st.moduleSpecifier.text) !== target) continue;
        const nb = st.importClause?.namedBindings;
        if (nb && ts.isNamedImports(nb))
          for (const el of nb.elements)
            if ((el.propertyName ?? el.name).text === w.fname) locals.add(el.name.text);
        if (nb && ts.isNamespaceImport(nb)) namespaces.add(nb.name.text);
      }
      if (!locals.size && !namespaces.size) continue;
      const callers = p.calls.filter((c) => {
        const e = unwrap(c.expression);
        if (ts.isIdentifier(e)) return locals.has(e.text);
        return (
          ts.isPropertyAccessExpression(e) &&
          e.name.text === w.fname &&
          ts.isIdentifier(e.expression) &&
          namespaces.has(e.expression.text)
        );
      });
      external += callers.length;
      out.push(...wrapperCallers(p, w, callers));
    }
    if (external && w.orphan) out.splice(out.indexOf(w.orphan), 1);
  }
  return out;
}

function tsFiles(dir: string): string[] {
  const out: string[] = [];
  for (const n of readdirSync(dir).sort()) {
    const p = join(dir, n);
    if (statSync(p).isDirectory()) out.push(...tsFiles(p));
    else if (n.endsWith(".ts") && !n.endsWith(".d.ts")) out.push(p);
  }
  return out;
}

export interface Violation {
  at: string;
  problem: string;
}

/** Calls to Bohemia functions that send an undeclared key, or that this scan cannot verify. */
export function violations(findings: CallFinding[], table: readonly ContractRow[]): Violation[] {
  const out: Violation[] = [];
  for (const f of findings) {
    const at = `${f.file}:${f.line}`;
    if (f.name === null) {
      out.push({ at, problem: f.why ?? "computed APIFunc" });
      continue;
    }
    if (f.name.startsWith(OWN_PREFIX)) continue;
    const row = table.find((r) => r.name === f.name);
    if (!row) {
      out.push({
        at,
        problem: `${f.name} is not a Bohemia handler or native function in the table`,
      });
      continue;
    }
    if (f.keys === null) {
      out.push({ at, problem: `${f.name}: ${f.why ?? "request keys cannot be read"}` });
      continue;
    }
    for (const k of f.keys)
      if (!row.request.includes(k))
        out.push({
          at,
          problem: `${f.name} does not declare request field "${k}" (declares ${JSON.stringify(row.request)}; ${row.ref})`,
        });
  }
  return out;
}

/** The directories scanned. Scripts under scripts/ (netcall.ts and the like) take the APIFunc at run time. */
const SCANNED_DIRS = ["src/tools", "src/workbench"];

function scanRepo(): CallFinding[] {
  const files: { file: string; text: string }[] = [];
  for (const dir of SCANNED_DIRS)
    for (const f of tsFiles(join(REPO_ROOT, dir)))
      files.push({
        file: relative(REPO_ROOT, f).replace(/\\/g, "/"),
        text: readFileSync(f, "utf-8"),
      });
  return scanFiles(files);
}

// ── The repository's calls ────────────────────────────────────────────────────

describe("calls to Bohemia NET handlers send only declared request fields", () => {
  const findings = scanRepo();
  const bohemia = findings.filter((f) => f.name !== null && !f.name.startsWith(OWN_PREFIX));

  it("finds exactly the known Bohemia call sites (seven tool call sites, the client's handler recovery, the six native wrappers, wb_bi's 14 read handlers)", () => {
    // Pinned: a new call to a Bohemia function is added here once its request
    // keys pass the check below.
    expect(bohemia.map((f) => `${f.file} ${f.name}`).sort()).toEqual([
      "src/tools/wb-prefabs.ts GetPrefabGUID",
      "src/tools/wb-prefabs.ts LocatePrefabsFromPath",
      "src/tools/wb-prefabs.ts LocateProject",
      "src/tools/wb-projects.ts GetLoadedProjects",
      "src/tools/wb-projects.ts LocateProject",
      "src/tools/wb-resources.ts GetResourceInfo",
      // W7 K1 route (DEC-075): wb_terrain_edit sends ExportTerrain only under terrain_write_route exportTerrain.
      "src/tools/wb-terrain-edit.ts ExportTerrain",
      // wb_validate left TextureValidator and MaterialValidator for EMCP_WB_Validate (W2 OD-7, KD-011).
      // wb_bi: the 14 verified read-only handlers (DEC-047 L6), one call site each.
      "src/workbench/bi-handlers.ts AnimExportProfileChannels",
      "src/workbench/bi-handlers.ts AnimExportProfiles",
      "src/workbench/bi-handlers.ts CheckGUID",
      "src/workbench/bi-handlers.ts GetGameMaterials",
      "src/workbench/bi-handlers.ts GetLoadedProjects",
      "src/workbench/bi-handlers.ts GetPathToAssetsFromGuids",
      "src/workbench/bi-handlers.ts GetPrefabChildInfo",
      "src/workbench/bi-handlers.ts GetPrefabGUID",
      "src/workbench/bi-handlers.ts GetRelativePath",
      "src/workbench/bi-handlers.ts GetResourceInfo",
      "src/workbench/bi-handlers.ts LoadedProjects",
      "src/workbench/bi-handlers.ts LocateProject",
      "src/workbench/bi-handlers.ts PrefabImporter",
      "src/workbench/bi-handlers.ts TextureValidation",
      "src/workbench/client.ts GetLoadedProjects",
      // DEC-107 (total audit live-client-04): openProjectMatch asks which project is loaded.
      "src/workbench/client.ts GetLoadedProjects",
      // Engine natives wrapped in native.ts (DEC-048 package A); payloads per DEC-040 and
      // scripts/live/s-c-natives.ts, checked against DECLARED below and in tests/workbench/native.test.ts.
      "src/workbench/native.ts BringModuleWindowToFront",
      "src/workbench/native.ts IsWorkbenchRunning",
      // W8 TS-6: wb_scripts status reads IsWorldEditorRunning.
      "src/workbench/native.ts IsWorldEditorRunning",
      "src/workbench/native.ts OpenResource",
      "src/workbench/native.ts ReloadScripts",
      "src/workbench/native.ts ValidateScripts",
    ]);
    expect(new Set(bohemia.map((f) => f.name)).size).toBe(22);
  });

  it("every NET call names its APIFunc (directly or through a wrapper's caller)", () => {
    expect(findings.filter((f) => f.name === null)).toEqual([]);
  });

  it("no call sends a key the Bohemia function does not declare", () => {
    expect(violations(findings, DECLARED)).toEqual([]);
  });
});

// ── The checker itself ────────────────────────────────────────────────────────

describe("the contract checker", () => {
  const src = [
    "async function wbCall(client: C, apiFunc: string, params: Record<string, unknown>) {",
    "  return client.call(apiFunc, params);",
    "}",
    "export async function f(client: C, p: string) {",
    '  await client.call<Record<string, unknown>>("LocateProject", { path: p });',
    '  await client.call("LocateProject", { path: p, projectName: "x" });',
    '  await (client.call as (m: string, a: object) => Promise<unknown>)("GetPrefabGUID", { prefabPath: p, guid: "g" });',
    '  await client.call("GetLoadedProjects");',
    '  await wbCall(client, "EMCP_WB_CreateEntity", { prefab: p });',
    '  await wbCall(client, "CheckGUID", { matName: p, other: 1 });',
    "  const params = { path: p };",
    '  await client.call("LocateProject", params);',
    '  await client.call("NoSuchHandler", {});',
    "}",
  ].join("\n");
  const findings = scanSource("synthetic.ts", src);

  it("reads literal names, typed and cast callees, wrappers and omitted requests", () => {
    expect(findings.map((f) => [f.name, f.keys])).toEqual([
      ["EMCP_WB_CreateEntity", ["prefab"]],
      ["CheckGUID", ["matName", "other"]],
      ["LocateProject", ["path"]],
      ["LocateProject", ["path", "projectName"]],
      ["GetPrefabGUID", ["prefabPath", "guid"]],
      ["GetLoadedProjects", []],
      ["LocateProject", null],
      ["NoSuchHandler", []],
    ]);
  });

  it("fails on an undeclared key, an unreadable request and an unknown function", () => {
    const v = violations(findings, DECLARED).map((x) => x.problem);
    expect(v).toHaveLength(5);
    expect(v.filter((p) => /does not declare request field "projectName"/.test(p))).toHaveLength(1);
    expect(v.filter((p) => /does not declare request field "guid"/.test(p))).toHaveLength(1);
    expect(v.filter((p) => /does not declare request field "other"/.test(p))).toHaveLength(1);
    expect(v.filter((p) => /request is not an object literal/.test(p))).toHaveLength(1);
    expect(v.filter((p) => /NoSuchHandler is not a Bohemia handler/.test(p))).toHaveLength(1);
  });

  it("sees element-access, destructured and encodeRequest calls", () => {
    const f = scanSource(
      "y.ts",
      [
        "async function h(client: C, p: string) {",
        '  await client["call"]("LocateProject", { path: p, a: 1 });',
        "  const { call } = client;",
        '  await call("LocateProject", { b: 2 });',
        '  encodeRequest(1, "LocateProject", { c: 3 });',
        "}",
      ].join("\n"),
    );
    expect(f.map((x) => [x.name, x.keys])).toEqual([
      ["LocateProject", ["path", "a"]],
      ["LocateProject", ["b"]],
      ["LocateProject", ["c"]],
    ]);
    expect(violations(f, DECLARED)).toHaveLength(3);
  });

  it("resolves an exported wrapper at its callers in other files", () => {
    const files = [
      {
        file: "src/tools/wrap.ts",
        text: [
          "export async function wbCall(client: C, apiFunc: string, params: object) {",
          "  return client.call(apiFunc, params);",
          "}",
          'export async function local(c: C) { await wbCall(c, "LocateProject", { path: "x" }); }',
        ].join("\n"),
      },
      {
        file: "src/tools/user.ts",
        text: [
          'import { wbCall as w } from "./wrap.js";',
          'import * as ns from "./wrap.js";',
          'export async function u(c: C) { await w(c, "LocateProject", { path: "y", extra: 1 }); }',
          'export async function v(c: C) { await ns.wbCall(c, "CheckGUID", { matName: "z" }); }',
        ].join("\n"),
      },
      {
        file: "src/tools/orphan.ts",
        text: "export async function fwd(client: C, apiFunc: string) { return client.call(apiFunc, {}); }",
      },
      {
        file: "src/tools/orphan-user.ts",
        text: 'import { fwd } from "./orphan.js";\nexport const go = (c: C) => fwd(c, "GetLoadedProjects");',
      },
    ];
    const f = scanFiles(files);
    expect(f.map((x) => [x.file, x.name, x.keys])).toEqual([
      ["src/tools/wrap.ts", "LocateProject", ["path"]],
      ["src/tools/user.ts", "LocateProject", ["path", "extra"]],
      ["src/tools/user.ts", "CheckGUID", ["matName"]],
      ["src/tools/orphan-user.ts", "GetLoadedProjects", []],
    ]);
    expect(violations(f, DECLARED).map((v) => v.problem)).toEqual([
      expect.stringMatching(/does not declare request field "extra"/),
    ]);
  });

  it("flags an APIFunc it cannot resolve", () => {
    const f = scanSource("x.ts", "async function g(c: C, n: string) { await c.call(n, {}); }");
    expect(f).toHaveLength(1);
    expect(f[0].name).toBeNull();
    expect(violations(f, DECLARED)).toHaveLength(1);
  });
});

// ── Regenerate the table from the game's source (skipped without it) ─────────

async function regenerated(): Promise<ContractRow[] | null> {
  try {
    const build = (
      JSON.parse(
        readFileSync(join(REPO_ROOT, "data", "census", "current-build.json"), "utf-8"),
      ) as {
        tag: string;
      }
    ).tag;
    const { loadSourceIndex } = await import("../../src/census/source-index.js");
    const { artifactsDir } = await import("../../scripts/live/paths.js");
    const index = loadSourceIndex(build, { dir: artifactsDir() });
    if (!index) return null;
    const { loadConfig } = await import("../../src/config.js");
    const gamePath = loadConfig().gamePath;
    if (!gamePath || !existsSync(join(gamePath, "addons"))) return null;
    const { PakVirtualFS } = await import("../../src/pak/vfs.js");
    const vfs = PakVirtualFS.get(gamePath);
    if (!vfs) return null;
    const { analyze, pakBackend } =
      await import("../../scripts/census/enumerators/e04-net-surface.js");
    return analyze(index, pakBackend(vfs)).table;
  } catch {
    return null;
  }
}

const REGEN = await regenerated();

describe.skipIf(!INSTALL_IS_CENSUS_BUILD || REGEN === null)(
  "the table matches the game's script source",
  () => {
    it("regenerates to the same rows", () => {
      expect(REGEN).toEqual(DECLARED);
    });
  },
);
